<?php
/**
 * Sharclean Admin – Secure CV download
 * Usage: admin/cv.php?f=cv_abc123.pdf
 */

declare(strict_types=1);

require_once __DIR__ . '/auth.php';

$filename = basename($_GET['f'] ?? '');

// Only allow filenames generated by apply.php (cv_ prefix + safe chars)
if (!$filename || !preg_match('/^cv_[a-zA-Z0-9._-]+\.(pdf|docx?)$/i', $filename)) {
    http_response_code(400);
    exit('Archivo no válido.');
}

$path = realpath(__DIR__ . '/../uploads/cvs/' . $filename);
$base = realpath(__DIR__ . '/../uploads/cvs/');

// Prevent directory traversal
if (!$path || !$base || !str_starts_with($path, $base)) {
    http_response_code(404);
    exit('Archivo no encontrado.');
}

$ext   = strtolower(pathinfo($path, PATHINFO_EXTENSION));
$types = [
    'pdf'  => 'application/pdf',
    'doc'  => 'application/msword',
    'docx' => 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
];

header('Content-Type: ' . ($types[$ext] ?? 'application/octet-stream'));
header('Content-Disposition: inline; filename="' . $filename . '"');
header('Content-Length: ' . filesize($path));
readfile($path);
